arguments.command:
cd /app; grep -v stats logs/service.log; mkdir -p /tmp/w; cat > /tmp/w/run.py <<'E'
import sys,re,shutil,subprocess,os
fixes={
'utm':('shelfmark/keys.py','if name in cfg.ignore_params:','if name in cfg.ignore_params or name.startswith("utm_"):'),
'loc':('shelfmark/locale.py','return rng\n','return loc\n'),
'purge':('shelfmark/cache.py','prefix = f"{route}|{ident}"','prefix = f"{route}|{ident}|"'),
'ttl':('shelfmark/config.py','return int(value)\n','return int(value) * 1000\n'),
}
def variant(names):
    d=f'/tmp/w/v_{"_".join(names) or "base"}'
    shutil.rmtree(d,ignore_errors=True); shutil.copytree('/app/shelfmark',d+'/shelfmark')
    for n in names:
        f,a,b=fixes[n]; p=d+'/'+f; s=open(p).read(); assert a in s; open(p,'w').write(s.replace(a,b,1))
    return d
def run(names):
    d=variant(names)
    out=subprocess.run(['python3','/app/tools/replay.py','--pkg',d,'--diff'],capture_output=True,text=True).stdout
    return out
if __name__=='__main__':
    names=sys.argv[1:] if sys.argv[1:]!=['none'] else []
    for l in run(names).splitlines():
        m=re.match(r'(r\d+) (\S+) .*logged=(\S+) replay=(\S+)',l)
        if m and m.group(2)>='2027-05-03T14:00:01' : print(l)
        elif l.startswith('#'): print(l)
E
python3 /tmp/w/run.py none | grep -c 'logged=miss replay=hit'
for n in utm loc purge ttl; do echo $n; python3 /tmp/w/run.py $n | grep 'logged=miss replay=hit' | sed -n '1p;$p' ; python3 /tmp/w/run.py $n | grep -c 'logged=miss replay=hit'; done

